def word_break(s, word_dict):
    if not s: return []
    ws, memo = set(word_dict), {}
    def dfs(rem):
        if not rem: return [""]
        if rem in memo: return memo[rem]
        res = []
        for w in ws:
            if rem.startswith(w):
                for t in dfs(rem[len(w):]):
                    res.append(w + (" " + t if t else ""))
        memo[rem] = res
        return res
    return sorted(dfs(s))
